import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { ChevronDown, Search, Menu, X, LogIn, Facebook, Mail, Phone } from 'lucide-react'; // Import icons

export default function Header() {
  // State to manage dropdown visibility, mobile menu toggler, selected location, and login modal visibility
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [selectedLocation, setSelectedLocation] = useState('Lefkosia'); // Default location
  const [searchQuery, setSearchQuery] = useState("");
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false); // Add state for login modal

  const navigate = useNavigate(); // Add useNavigate hook

  // Toggle dropdown visibility
  const toggleDropdown = () => {
    setIsDropdownOpen((prev) => !prev);
  };

  // Toggle mobile menu visibility
  const toggleMobileMenu = () => {
    setIsMobileMenuOpen((prev) => !prev);
  };

  // Toggle login modal visibility
  const toggleLoginModal = () => {
    setIsLoginModalOpen((prev) => !prev);
  };

  // Update the selected location
  const handleLocationChange = (location) => {
    setSelectedLocation(location);
    setIsDropdownOpen(false); // Close the dropdown after selection
  };

  // Handle search form submission
  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      // Do nothing here, as the Link will handle the navigation
    }
  };

  return (
    <header className="bg-white mt-0">
      <div className="container mx-auto px-4 py-4 flex items-center">
        {/* Left Section: Logo */}
        <div className="flex items-center space-x-6">
          <Link to="/">
            <img src="/k1.jpeg" alt="Logo" className="w-[120px] h-auto" />
          </Link>
          {/* Dropdown for Location */}
          <div className="relative hidden md:block">
            <button
              onClick={toggleDropdown}
              className="flex items-center text-gray-600 hover:text-gray-800 space-x-2"
            >
              <span className="text-red-600">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="w-5 h-5"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M12 11c0 1.657-1.343 3-3 3s-3-1.343-3-3 1.343-3 3-3 3 1.343 3 3zM12 11v3m6-6a9 9 0 11-6-6c1.488-.276 2.815 0.374 3.514 1.47M6.343 6.343l1.414 1.414M15.88 15.88a3 3 0 004.243 0 3 3 0 00.273-4.01m0 0l-1.414-1.414M18 18v3m0 0h-3m3 0a9 9 0 11-9-9m6-6v3"
                  />
                </svg>
              </span>
              {selectedLocation} <ChevronDown size={16} />
            </button>
            {/* Dropdown Menu */}
            {isDropdownOpen && (
              <div className="absolute mt-2 bg-white shadow-lg rounded-md w-48 z-50 border border-gray-200">
                <ul>
                  {['Lefkosia', 'Magusa', 'Girne', 'Guzelyurt', 'Lefke', 'Iskele'].map((location) => (
                    <li
                      key={location}
                      onClick={() => handleLocationChange(location)}
                      className="px-4 py-2 hover:bg-gray-100 cursor-pointer"
                    >
                      {location}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        </div>

        {/* Middle Section: Search Bar */}
        <div className="flex-grow mx-6">
          <form onSubmit={handleSearch} className="flex items-center bg-gray-100 rounded-md">
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Find Cars, Mobile Phones and more..."
              className="flex-grow p-2 bg-transparent focus:outline-none"
            />
            <Link to={`/search?query=${searchQuery}`} className="p-2 bg-red-500 text-white rounded-r-md">
              <Search size={24} />
            </Link>
          </form>
        </div>

        {/* Right Section: Options */}
        <div className="flex items-center space-x-4">
          {/* Toggler for Mobile Menu */}
          <button
            onClick={toggleMobileMenu}
            className="block md:hidden text-gray-600 hover:text-gray-800"
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
          <button className="hidden md:block text-gray-600 border-b-2 border-transparent hover:border-red-500">Sign up</button>
          <button
            className="hidden md:block text-gray-600 border-b-2 border-transparent hover:border-red-500"
            onClick={toggleLoginModal} // Add onClick handler for login modal
          >
            Login
          </button>
          <Link to="/sell" className="hidden md:block bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700">
            Sell
          </Link>
        </div>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="md:hidden bg-white border-t">
          <div className="px-4 py-4">
            {/* Dropdown for Location */}
            <div className="relative mb-4">
              <button
                onClick={toggleDropdown}
                className="flex items-center text-gray-600 hover:text-gray-800 space-x-2"
              >
                <span>{selectedLocation}</span> <ChevronDown size={16} />
              </button>
              {isDropdownOpen && (
                <div className="absolute mt-2 bg-white shadow-lg rounded-md w-full z-50 border border-gray-200">
                  <ul>
                    {['Lefkosia', 'Magusa', 'Girne', 'Guzelyurt', 'Lefke', 'Iskele'].map((location) => (
                      <li
                        key={location}
                        onClick={() => handleLocationChange(location)}
                        className="px-4 py-2 hover:bg-gray-100 cursor-pointer"
                      >
                        {location}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
            {/* Other Options */}
            <div className="space-y-4">
              <button className="text-gray-600 border-b-2 border-transparent hover:border-red-500">Sign up</button><br/>
              <button
                className="text-gray-600 border-b-2 border-transparent hover:border-red-500"
                onClick={toggleLoginModal} // Add onClick handler for login modal
              >
                Login
              </button>
              <Link
                to="/sell"
                className="block bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700"
              >
                Sell
              </Link>
            </div>
          </div>
        </div>
      )}

      {/* Categories (Optional) */}
      <div className="container mx-auto px-4 py-2 border-t border-gray-200">
        <div className="flex flex-wrap space-x-4 text-gray-600 justify-center">
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=Vehicles`)} // Add onClick handler
          >
            Vehicles
          </button>
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=Properties`)} // Add onClick handler
          >
            Properties
          </button>
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=Mobiles & Tablets`)} // Add onClick handler
          >
            Mobiles & Tablets
          </button>
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=Jobs`)} // Add onClick handler
          >
            Jobs
          </button>
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=Electronics & Appliances`)} // Add onClick handler
          >
            Electronics & Appliances
          </button>
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=Furniture & Decor`)} // Add onClick handler
          >
            Furniture & Decor
          </button>
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=More Categories`)} // Add onClick handler
          >
            More Categories
          </button>
        </div>
      </div>

      {/* Login Modal */}
      {isLoginModalOpen && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
          <div className="bg-white rounded-lg shadow-lg p-6 w-full max-w-md mx-4">
            <div className="flex justify-center mb-4">
              <Link to="/">
                <img src="/k1.jpeg" alt="Logo" className="w-[120px] h-auto" />
              </Link>
            </div>
            <h2 className="text-xl font-semibold mb-4 text-center">Login into your Kibzar account</h2>
            <button className="bg-blue-500 text-black w-full py-2 rounded-md mb-2 hover:bg-blue-600 flex items-center justify-center">
              <LogIn className="mr-2" /> Login with Google
            </button>
            <button className="bg-blue-700 text-white w-full py-2 rounded-md mb-2 hover:bg-blue-800 flex items-center justify-center">
              <Facebook className="mr-2" /> Login with Facebook
            </button>
            <div className="text-center my-4">Or</div>
            <button className="bg-gray-200 text-gray-800 w-full py-2 rounded-md mb-2 hover:bg-gray-300 flex items-center justify-center">
              <Mail className="mr-2" /> Login with Email
            </button>
            <button className="bg-gray-200 text-gray-800 w-full py-2 rounded-md mb-2 hover:bg-gray-300 flex items-center justify-center">
              <Phone className="mr-2" /> Login with Phone
            </button>
            <button
              className="mt-4 text-red-500 hover:underline"
              onClick={toggleLoginModal} // Close modal on click
            >
              Close
            </button>
          </div>
        </div>
      )}
    </header>
  );
}
